from pathlib import Path
import sys,json,gzip,base64
root=Path(sys.argv[1])

def dec(s): return gzip.decompress(base64.b64decode(s)).decode('utf-8')
MAIN=''
CSS=''
HOSTJS=''
main=root/'app/src/main/java/edu/gascnagercoil/environmentalsciences/MainActivity.java'
main.write_text(dec(MAIN),encoding='utf-8')
idx=root/'app/src/main/assets/index.html'
s=idx.read_text(encoding='utf-8')
# Append the authoritative final mobile override and host bridge.
if 'v1.2.9 native ScrollView host' not in s:
    s=s.replace('</style><meta content="#1f6552"',dec(CSS)+'\n</style><meta content="#1f6552"',1)
if 'window.reportHostHeight=function()' not in s:
    s=s.replace('</body>',dec(HOSTJS)+'\n</body>',1)
marker="if(typeof window.placeApkFooterOnFinalPage==='function')window.placeApkFooterOnFinalPage();"
if marker in s and "window.reportHostHeight==='function')window.reportHostHeight();" not in s[s.index(marker):s.index(marker)+300]:
    s=s.replace(marker,marker+"\n    if(typeof window.reportHostHeight==='function')window.reportHostHeight();",1)
s=s.replace("if(requestId===renderRequestId)p.removeAttribute('aria-busy');","if(requestId===renderRequestId){p.removeAttribute('aria-busy');if(typeof window.reportHostHeight==='function')window.reportHostHeight();}",1)
s=s.replace('v1.2.8','v1.2.9')
idx.write_text(s,encoding='utf-8')
# version metadata
g=root/'app/build.gradle'; t=g.read_text(); t=t.replace('versionCode 10208','versionCode 10209').replace("versionName '1.2.8'","versionName '1.2.9'"); g.write_text(t)
c=root/'app/src/main/assets/book-catalog.json'; obj=json.loads(c.read_text()); obj['version']='1.2.9'; c.write_text(json.dumps(obj,ensure_ascii=False,indent=2)+'\n')
# carry v1.2.8 content hashes into v1.2.9 revision manifest
m8=root/'verification/content-revision-manifest-v1.2.8.json'; obj=json.loads(m8.read_text()); obj['release']='1.2.9'; obj['previous_release']='1.2.8'; obj['purpose']='Native ScrollView host and deterministic native-navigation correction.'; obj['content_change']=False; obj['reader_changes']=['Native ScrollView owns vertical scrolling instead of WebView','WebView expands to rendered document height through AndroidHost bridge','Native Previous/Next index is synchronized after every render','Language/visual changes trigger native height recalculation','Legacy HTML toolbar stays hidden on phones']; (root/'verification/content-revision-manifest-v1.2.9.json').write_text(json.dumps(obj,ensure_ascii=False,indent=2)+'\n')
meta=root/'verification/app-build-metadata.json'; obj=json.loads(meta.read_text()); obj['version_name']='1.2.9'; obj['version_code']=10209; obj['app_version']='1.2.9'; obj['content_revision']='v1.2.9 native ScrollView host; educational unit payloads unchanged'; obj['content_revision_manifest']='verification/content-revision-manifest-v1.2.9.json'; meta.write_text(json.dumps(obj,ensure_ascii=False,indent=2)+'\n')
v=root/'tools/verify_content_integrity.py'; t=v.read_text(); t=t.replace('content-revision-manifest-v1.2.8.json','content-revision-manifest-v1.2.9.json').replace("'1.2.8'","'1.2.9'").replace('versionCode 10208','versionCode 10209').replace('v1.2.8','v1.2.9'); v.write_text(t)
print('v1.2.9 patch applied')
